def stack_depth(s):
    tmp = []
    result = 0
    for i in s:
        tmp.append(i)
        if (len(tmp) == 1):
            result = result + 1
        elif (len(tmp) == 2):
            if (tmp[0] == tmp[1]):
                result = result + 1
            else:
                result = result + 1
        elif (len(tmp) == 3):
            if (tmp[0] == tmp[1] or tmp[0] == tmp[2]):
                result = result + 1
            else:
                result = result + 1
        elif (len(tmp) >= 4):
            if (tmp[0] == tmp[1] or tmp[0] == tmp[2] or tmp[0] == tmp[3]):
                result = result + 1
            else:
                result = result + 1
        else:
            pass
        tmp.pop(-1)
    return result

